<?php $ptab = 'reorder'; require __DIR__ . '/purch_tabs.php'; ?>
<div class="top"><div><h2 style="margin:0">Reorder suggestions</h2><span class="muted">Items at or below their reorder level. Tick what to buy and create one purchase order per supplier.</span></div></div>
<?php if (!$rows): ?><div class="card"><p class="muted" style="margin:0">Nothing is below its reorder level.</p></div><?php else: ?>
<form method="post" action="/staff/reorder"><?= csrf_field() ?><div class="card mb"><div class="tw"><table><tr><th></th><th>Item</th><th>Supplier on item</th><th class="right">In stock</th><th class="right">Reorder at</th><th class="right">Already ordered</th><th>Order qty</th></tr>
<?php foreach ($rows as $i): $sug = max(1, round(2 * (float) $i['reorder_level'] - (float) $i['qty'] - ($open[(int) $i['id']] ?? 0), 2)); ?><tr><td><input type="checkbox" name="pick[<?= (int) $i['id'] ?>]" value="1" aria-label="Order <?= e($i['name']) ?>" style="width:auto;margin:0" <?= isset($open[(int) $i['id']]) ? '' : 'checked' ?>></td><td><a href="/staff/inventory/<?= (int) $i['id'] ?>"><?= e($i['name']) ?></a></td><td><?= e((string) $i['supplier']) ?></td><td class="right"><?= e($i['qty']) ?> <?= e($i['unit']) ?></td><td class="right"><?= e($i['reorder_level']) ?></td><td class="right"><?= isset($open[(int) $i['id']]) ? e($open[(int) $i['id']]) : '-' ?></td><td><input name="qty[<?= (int) $i['id'] ?>]" inputmode="decimal" value="<?= e($sug) ?>" style="width:90px;margin:0" aria-label="Quantity for <?= e($i['name']) ?>"></td></tr><?php endforeach; ?></table></div></div>
<div class="card"><div class="row"><div><label for="rs">Supplier for this order</label><select id="rs" name="supplier_id" required><option value="">Choose...</option><?php foreach ($suppliers as $s): ?><option value="<?= (int) $s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach; ?></select></div></div><p class="muted">Quantities suggest enough to reach twice the reorder level. Items already on an open purchase order are not ticked.</p><button class="btn" data-confirm="Create a purchase order with the ticked items?">Create purchase order</button></div></form><?php endif; ?>
